       if(exists){setMessage("This brokerage is already in the directory.");return}
       const sideKey=key==="listing_brokerage_name"?"listing_brokerage":"buyer_brokerage";
       const p={company_name:value,brokerage_name:value,address:form[sideKey+"_address"]||null,unit:form[sideKey+"_unit"]||null,city:form[sideKey+"_city"]||null,province:form[sideKey+"_province"]||"ON",postal_code:form[sideKey+"_postal_code"]||null,phone:form[sideKey+"_phone"]||null,fax:form[sideKey+"_fax"]||null,charges_hst:true};
