 function updateBulkGroup(id,patch){setBulkGroups(old=>{let next=old.map(g=>g.id===id?{...g,...patch,label:patch.type!==undefined?(docTypes.find(([t])=>t===patch.type)?.[1]||patch.type):g.label}:g);if(bulkPageCount>0){const pagesFor=g=>{const spec=String(g.pages||"").trim();if(spec){const out=[];for(const part of spec.split(",").map(x=>x.trim()).filter(Boolean)){const m=part.match(/^(\\d+)(?:\\s*-\\s*(\\d+))?$/);if(!m)return[];const a=Number(m[1]),b=Number(m[2]||m[1]);if(a<1||b<a||b>bulkPageCount)return[];for(let n=a;n<=b;n++)out.push(n)}return [...new Set(out)]}const a=Number(g.start),b=Number(g.end);if(!Number.isInteger(a)||!Number.isInteger(b)||a<1||b<a||b>bulkPageCount)return[];return Array.from({length:b-a+1},(_,i)=>a+i)};const seen=new Set();next=next.filter(g=>{const pages=pagesFor(g);if(pages.length&&pages.every(p=>seen.has(p)))return false;pages.forEach(p=>seen.add(p));return true})}return next})}
